/**
 * @param {Function} fn
 * @param {number} t
 * @return {Function}
 */
var throttle = function(fn, t) {
    let timer = null;        // non-null while a throttle window is active
    let pendingArgs = null;  // latest arguments received during the window

    const startWindow = () => {
        timer = setTimeout(() => {
            if (pendingArgs !== null) {
                fn(...pendingArgs);   // run with the latest saved args
                pendingArgs = null;
                startWindow();        // and open another window
            } else {
                timer = null;         // window over; next call runs immediately
            }
        }, t);
    };

    return function(...args) {
        if (timer === null) {
            fn(...args);
            startWindow();
        } else {
            pendingArgs = args;
        }
    };
};
